#include <stdio.h>
#include <limits.h>
#define N 8
#define INF 999999
const char *names[N]={"Main Gate","Admin Block","CSE Department","Library","Canteen","Hostel","Auditorium","Bus Stop"};
int g[N][N]={{0,200,0,0,0,0,0,150},{200,0,120,0,0,0,180,0},{0,120,0,100,150,0,0,0},{0,0,100,0,100,200,0,0},{0,0,150,100,0,100,120,0},{0,0,0,200,100,0,0,150},{0,180,0,0,120,0,0,100},{150,0,0,0,0,150,100,0}};
void showpath(int p[],int t){int a[N],k=0;while(t!=-1){a[k++]=t;t=p[t];}for(int i=k-1;i>=0;i--){printf("%s",names[a[i]]);if(i)printf(" -> ");}puts("");}
void dijkstra(int s,int t){int d[N],p[N],v[N]={0};for(int i=0;i<N;i++)d[i]=INF,p[i]=-1;d[s]=0;for(int z=0;z<N;z++){int u=-1;for(int i=0;i<N;i++)if(!v[i]&&(u<0||d[i]<d[u]))u=i;if(u<0||d[u]==INF)break;v[u]=1;for(int j=0;j<N;j++)if(g[u][j]&&!v[j]&&d[u]+g[u][j]<d[j])d[j]=d[u]+g[u][j],p[j]=u;}printf("Dijkstra distance: %d m\n",d[t]);showpath(p,t);}
void traversal(int s,int t,int bfs){int seen[N]={0},p[N],q[100],front=0,rear=0,stack[100],top=0;for(int i=0;i<N;i++)p[i]=-1;if(bfs)q[rear++]=s;else stack[top++]=s;while((bfs?front<rear:top>0)){int u=bfs?q[front++]:stack[--top];if(seen[u])continue;seen[u]=1;if(u==t)break;if(bfs){for(int j=0;j<N;j++)if(g[u][j]&&!seen[j]&&p[j]==-1&&j!=s)p[j]=u,q[rear++]=j;}else{for(int j=N-1;j>=0;j--)if(g[u][j]&&!seen[j]&&p[j]==-1&&j!=s)p[j]=u,stack[top++]=j;}}printf("%s traversal path:\n",bfs?"BFS":"DFS");showpath(p,t);}
void mst(int kruskal){int parent[N],used[N]={0},total=0,count=0;for(int i=0;i<N;i++)parent[i]=i;while(count<N-1){int best=INF,a=-1,b=-1;for(int i=0;i<N;i++)for(int j=i+1;j<N;j++)if(g[i][j]){if(kruskal){int x=i,y=j;while(parent[x]!=x)x=parent[x];while(parent[y]!=y)y=parent[y];if(x!=y&&g[i][j]<best)best=g[i][j],a=i,b=j;}else if(used[i]!=used[j]&&g[i][j]<best)best=g[i][j],a=i,b=j;}if(a<0)break;if(kruskal){int x=a,y=b;while(parent[x]!=x)x=parent[x];while(parent[y]!=y)y=parent[y];parent[x]=y;}else used[a]=used[b]=1;printf("%s -- %s : %d m\n",names[a],names[b],best);total+=best;count++;}printf("MST total: %d m\n",total);}
void floyd(int s,int t){int d[N][N],next[N][N];for(int i=0;i<N;i++)for(int j=0;j<N;j++)d[i][j]=i==j?0:(g[i][j]?g[i][j]:INF),next[i][j]=g[i][j]?j:-1;for(int k=0;k<N;k++)for(int i=0;i<N;i++)for(int j=0;j<N;j++)if(d[i][k]<INF&&d[k][j]<INF&&d[i][k]+d[k][j]<d[i][j])d[i][j]=d[i][k]+d[k][j],next[i][j]=next[i][k];printf("Floyd-Warshall distance: %d m\n",d[s][t]);if(s==t){puts(names[s]);return;}if(next[s][t]<0){puts("No route");return;}printf("%s",names[s]);while(s!=t){s=next[s][t];printf(" -> %s",names[s]);}puts("");}
int main(void){int choice,s,t;do{puts("\n=== CAMPUS NAVIGATION ===\n1 Dijkstra\n2 BFS\n3 DFS\n4 Prim MST\n5 Kruskal MST\n6 Floyd-Warshall\n0 Exit");printf("Choice: ");if(scanf("%d",&choice)!=1)break;if(choice>=1&&choice<=3||choice==6){for(int i=0;i<N;i++)printf("%d. %s\n",i,names[i]);printf("Source index: ");scanf("%d",&s);printf("Destination index: ");scanf("%d",&t);if(s<0||s>=N||t<0||t>=N){puts("Invalid location");continue;}}switch(choice){case 1:dijkstra(s,t);break;case 2:traversal(s,t,1);break;case 3:traversal(s,t,0);break;case 4:mst(0);break;case 5:mst(1);break;case 6:floyd(s,t);break;case 0:puts("Goodbye");break;default:puts("Invalid choice");}}while(choice!=0);return 0;}
